# Key poses for the fighter. He is shown from his left: the camera is on his +x side, he faces +y. A stance that
# shows the camera his chest therefore leads with the RIGHT foot and hand (the far side) and keeps the left hand
# back, near the camera. Limits: an arm reaches 49 cm from the shoulder, a leg 73 cm from the hip.
from poses_base import P, Mk, With, Knees, Toes, Also, V
def stance(p, kl=(0.9, 0.5, 0), kr=(-0.3, 1, 0), tl=(0.9, 0.3, -0.5), tr=(-0.2, 1, -0.5)): return Toes(Knees(p, kl, kr), tl, tr)
DN, DNr = V(0.5, -0.4, -1), V(-0.3, -0.3, -1)          # elbows hanging
BK, BKr = V(0.6, -1, 0.2), V(-0.6, -1, 0.2)             # elbows drawn back

# --- standing: low and coiled, weight between the feet, lead hand open, rear hand held back by the hip like a hidden blade
P['Idle'] = stance(With(Mk(V(0, -4, 71), 8, 14, -50, -35, -6, 42, V(22, -10, 90), V(-10, 40, 110), V(12, -38, 9), V(-8, 34, 9)), BK, DNr))
P['Idle2'] = stance(With(Mk(V(0, -5, 68), 11, 18, -52, -36, -8, 44, V(23, -12, 86), V(-10, 41, 106), V(12, -38, 9), V(-8, 34, 9)), BK, DNr))
P['WalkA'] = stance(With(Mk(V(0, 2, 73), 8, 12, -46, -32, -4, 38, V(22, -8, 92), V(-10, 40, 112), V(12, -30, 12), V(-8, 40, 9)), BK, DNr))
P['WalkB'] = stance(With(Mk(V(0, 6, 76), 6, 10, -42, -28, -4, 34, V(22, -4, 94), V(-10, 38, 114), V(12, 2, 20), V(-8, 36, 9)), BK, DNr))
P['WalkC'] = stance(With(Mk(V(0, 4, 75), 8, 12, -46, -32, -4, 38, V(22, -8, 92), V(-10, 40, 112), V(12, -8, 9), V(-8, 30, 9)), BK, DNr))
P['WalkD'] = stance(With(Mk(V(0, 0, 74), 10, 14, -50, -36, -4, 42, V(22, -12, 90), V(-10, 42, 110), V(12, -22, 9), V(-8, 44, 18)), BK, DNr))
P['Crouch'] = stance(With(Mk(V(0, -6, 44), 22, 30, -46, -30, -22, 36, V(20, -6, 52), V(-8, 38, 68), V(14, -30, 9), V(-10, 34, 9)), BK, DNr), V(1, 0.4, 0.3), V(-0.5, 1, 0.3))
# the dash is a ninja's: body thrown flat, both arms streaming behind
P['Dash'] = stance(With(Mk(V(0, 6, 60), 56, 64, -18, -12, -48, 14, V(22, -40, 80), V(-18, -44, 86), V(10, -48, 22), V(-8, 38, 9)), BK, BKr), V(0.3, 1, 0.2), V(-0.3, 1, 0.2), V(0.1, 0.4, -1), V(-0.2, 1, -0.4))
P['BackDash'] = stance(With(Mk(V(0, -12, 80), -20, -26, -56, -40, 18, 44, V(24, 6, 104), V(-12, 34, 118), V(12, -30, 9), V(-8, 24, 24)), DN, DNr))
P['Jump'] = stance(With(Mk(V(0, 0, 96), 18, 26, -40, -28, -14, 32, V(20, -14, 98), V(-12, 26, 112), V(10, -6, 46), V(-8, 22, 54)), BK, DNr), V(0.6, 1, 0), V(-0.3, 1, 0.3))
P['Fall'] = stance(With(Mk(V(0, 0, 96), -8, -14, -44, -30, 10, 36, V(36, -8, 134), V(-30, 8, 140), V(10, -14, 30), V(-8, 16, 24)), V(1, 0, -0.3), V(-1, 0, -0.3)), V(0.6, 1, 0), V(-0.3, 1, 0.2), V(0.3, 0.3, -1), V(-0.2, 0.5, -1))
P['BlockS'] = stance(With(Mk(V(0, -8, 73), 6, 10, -40, -30, -10, 34, V(10, 26, 114), V(-4, 30, 128), V(12, -38, 9), V(-8, 32, 9)), DN, DNr))
P['BlockC'] = stance(With(Mk(V(0, -6, 44), 20, 28, -40, -28, -22, 30, V(10, 26, 72), V(-4, 30, 86), V(14, -30, 9), V(-10, 34, 9)), DN, DNr), V(1, 0.4, 0.3), V(-0.5, 1, 0.3))
P['Hit'] = stance(With(Mk(V(0, -16, 76), -24, -36, -30, -24, -26, 26, V(26, -6, 110), V(-20, 20, 128), V(12, -40, 9), V(-8, 22, 14)), V(1, -0.3, -0.3), V(-1, 0.2, 0.2)))
# --- grounded strikes
P['LW'] = stance(With(Mk(V(0, -2, 71), 6, 12, -44, -32, -6, 36, V(22, -6, 96), V(-12, 20, 114), V(12, -38, 9), V(-8, 34, 9)), BK, V(-0.8, -0.6, -0.3)))
P['LS'] = stance(With(Mk(V(0, 8, 72), 16, 20, -72, -42, -8, 62, V(22, -4, 104), V(-6, 82, 130), V(12, -36, 9), V(-8, 42, 9)), BK, DNr))
P['MW'] = stance(With(Mk(V(0, -8, 71), -4, 2, -78, -48, -4, 68, V(26, -18, 100), V(-8, 34, 114), V(12, -40, 9), V(-8, 32, 9)), BK, DNr))
P['MS'] = stance(With(Mk(V(0, 22, 67), 30, 36, 24, -6, -30, -16, V(6, 102, 115), V(-22, 0, 92), V(12, -40, 13), V(-8, 54, 9)), V(0.3, -0.2, -1), BKr), V(0.4, 1, 0), V(-0.3, 1, 0.2), V(0.2, 0.6, -1), V(-0.2, 1, -0.5))
P['HW'] = stance(With(Mk(V(0, -12, 70), -12, -8, -86, -52, 0, 76, V(30, -34, 128), V(-8, 36, 110), V(12, -42, 9), V(-8, 30, 9)), V(0.6, -0.6, 0.8), DNr))
P['HS'] = stance(With(Mk(V(0, 40, 61), 42, 48, 44, 8, -40, -34, V(4, 118, 112), V(-26, -20, 98), V(12, -14, 14), V(-8, 78, 9)), V(0.3, -0.2, -1), BKr), V(0.3, 1, 0), V(-0.3, 1, 0.3), V(0.1, 0.5, -1), V(-0.2, 1, -0.5))
P['CL'] = stance(With(Mk(V(0, 14, 38), -12, -6, -50, -36, 4, 44, V(24, -24, 8), V(-10, 20, 60), V(14, -20, 9), V(-6, 86, 20)), V(0.8, -0.6, 0.3), DNr), V(1, 0.3, 0.4), V(-0.3, 0.3, 1), V(0.9, 0.3, -0.5), V(-0.1, 1, 0.2))
P['CM'] = stance(With(Mk(V(0, 44, 27), -30, -24, -64, -50, 22, 56, V(26, 10, 34), V(-20, 26, 5), V(6, 114, 12), V(-10, 20, 9)), V(0.8, -0.5, 0.5), V(-0.8, -0.3, 0.5)), V(0.3, 0.2, 1), V(-0.6, 0.3, 1), V(0.3, 1, 0.2), V(-0.4, 1, -0.4))
P['CHW'] = stance(With(Mk(V(0, 0, 42), 35, 45, -70, -46, -30, 56, V(26, -10, 40), V(-8, 30, 60), V(14, -30, 9), V(-10, 34, 9)), BK, DNr), V(1, 0.4, 0.3), V(-0.5, 1, 0.3))
P['CHS'] = stance(With(Mk(V(0, 24, 80), -6, -12, 36, 6, -16, -28, V(4, 44, 174), V(-24, -8, 96), V(12, 0, 12), V(-8, 40, 9)), V(0.5, -1, 0), BKr), V(0.5, 1, 0), V(-0.3, 1, 0.2), V(0.3, 0.6, -1), V(-0.2, 1, -0.5))
